// Traceback view toggle
function toggleTracebackView() {
  const tracebackView = document.getElementById("traceback-view");
  const interactiveView = document.getElementById("interactive-view");
  const toggleBtn = document.getElementById("view-toggle-btn");

  if (tracebackView.style.display === "none") {
    tracebackView.style.display = "block";
    interactiveView.style.display = "none";
    toggleBtn.textContent = "Interactive view";
  } else {
    tracebackView.style.display = "none";
    interactiveView.style.display = "block";
    toggleBtn.textContent = "Plaintext view";
  }
}

